def architecture():
    fig,ax=plt.subplots(figsize=(13,6)); ax.axis('off')
    labels=['User instruction','Mock agent /\ntool inference','Interaction graph\n(NetworkX)','Permission + risk\nassessment','Policy engine','ALLOW / BLOCK /\nHUMAN APPROVAL','Mock tool +\nSQLite audit']
    xs=[.04,.19,.34,.49,.64,.79,.92]
    for x,l in zip(xs,labels):
        ax.text(x,.54,l,ha='center',va='center',fontsize=10,color='white',weight='bold',bbox=dict(boxstyle='round,pad=.65',facecolor='#123B2A',edgecolor='#B89645'))
    for x in xs[:-1]: ax.annotate('',xy=(x+.105,.54),xytext=(x+.075,.54),arrowprops=dict(arrowstyle='->',color='#B89645',lw=2))
    ax.text(.5,.18,'Retrieved content enters as untrusted context; every execution event is serialized into the SQLite audit payload.',ha='center',fontsize=12,color='#173127')
    fig.tight_layout(); fig.savefig(OUT/'GraphGuard_Project_Architecture.png',dpi=180,bbox_inches='tight'); plt.close(fig)

def styles():
    s=getSampleStyleSheet(); s.add(ParagraphStyle(name='TitleGreen',parent=s['Title'],fontName='Helvetica-Bold',fontSize=28,leading=34,textColor=GREEN,alignment=TA_CENTER,spaceAfter=18)); s.add(ParagraphStyle(name='H1G',parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=18,leading=23,textColor=GREEN,spaceBefore=14,spaceAfter=8)); s.add(ParagraphStyle(name='H2G',parent=s['Heading2'],fontName='Helvetica-Bold',fontSize=13,leading=17,textColor=GREEN,spaceBefore=10,spaceAfter=5)); s.add(ParagraphStyle(name='BodyG',parent=s['BodyText'],fontName='Helvetica',fontSize=9.2,leading=13,textColor=INK,spaceAfter=6)); s.add(ParagraphStyle(name='SmallG',parent=s['BodyText'],fontName='Helvetica',fontSize=7.4,leading=9,textColor=INK)); s.add(ParagraphStyle(name='CodeG',parent=s['Code'],fontName='Courier',fontSize=7.3,leading=9,backColor=colors.HexColor('#E8EEE7'),leftIndent=8,rightIndent=8,spaceAfter=7)); return s
S=styles()
def P(x,style='BodyG'): return Paragraph(x,S[style])
def tbl(headers,rows,widths=None,small=True):
    data=[[P(h,'SmallG') for h in headers]]+[[P(str(c),'SmallG' if small else 'BodyG') for c in r] for r in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT'); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),GREEN),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#A9B7AD')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#EEF2EB')])]))
    return t
def footer(canvas,doc):
    canvas.saveState(); canvas.setStrokeColor(GOLD); canvas.line(1.6*cm,1.35*cm,19.4*cm,1.35*cm); canvas.setFillColor(GREEN); canvas.setFont('Helvetica',8); canvas.drawString(1.6*cm,.85*cm,'GraphGuard | DTU B.Tech CSE | Evidence-based codebase report'); canvas.drawRightString(19.4*cm,.85*cm,f'Page {doc.page}'); canvas.restoreState()
def build(path,story):
    d=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=1.55*cm,leftMargin=1.55*cm,topMargin=1.65*cm,bottomMargin=1.7*cm,title='GraphGuard Documentation'); d.build(story,onFirstPage=footer,onLaterPages=footer)
def cover(title,subtitle):
    return [Spacer(1,5*cm),P('GRAPHGUARD','TitleGreen'),P(title,'TitleGreen'),Spacer(1,.5*cm),P(subtitle,'BodyG'),Spacer(1,1.5*cm),P('<b>Delhi Technological University</b><br/>B.Tech Computer Science and Engineering<br/>Group A3<br/><br/>Jivesh Somya - 23/CS/195<br/>Gaurav Garg - 23/CS/155<br/>Himanshu Meena - 23/CS/177<br/><br/>Faculty Supervisor: Col R Sreejeth','BodyG'),PageBreak()]
def H(t): return [P(t,'H1G')]

