def comprehensive():
    story=cover('Codebase Technical Documentation and Development Progress Report','Risk-Aware Security and Evaluation Framework for Tool-Using Large Language Model Agents')
    story += H('1. Executive Summary')+[P('This report is based on direct inspection of the current workspace, source files, generated reports and tests. GraphGuard is a working offline demonstration of risk-aware tool execution. Its active runtime is the root <b>app/</b> package. The system is intentionally simulated: tools, data, agent selection and approvals are local mock behavior, not external LLM, banking, email, or MCP integration.'),P('The codebase contains five primary active Python modules, two test files, six registered mock tools, 20 deterministic scenarios and a SQLite database. Duplicate files under <b>backend/app</b> and <b>frontend/app.py</b> exist, but the root Docker command targets <b>app.main:app</b>.')]
    story += H('2. Table of Contents')+[P('3 Project inventory and module map<br/>4 Technology stack<br/>5 Architecture and execution flow<br/>6 Core implementation<br/>7 API reference<br/>8 Development status<br/>9 Evaluation results<br/>10 Security analysis<br/>11 Installation guide<br/>12 Roadmap and team contribution') ,PageBreak()]
    story += H('3. Actual Project Inventory')+[tbl(['Location','Responsibility','Important symbols','Why it matters'],inventory,[3*cm,4.1*cm,4.7*cm,5.2*cm]),Spacer(1,8),P('The workspace also contains reports, docs, a generated presentation, .env.example, requirements.txt and graphguard.db. There is no committed Git history: Git reports that master has no commits. Therefore no individual authorship claims can be supported from version control.'),PageBreak()]
    story += H('4. Technology Stack')+[tbl(['Technology','Where used','Purpose','Status / selection rationale'],tech,[3*cm,3.7*cm,4.1*cm,6.2*cm]),PageBreak()]
    story += H('5. Actual System Architecture')+[P('The actual path begins at a FastAPI request or Streamlit direct call. <b>execute()</b> uses keyword matching in <b>infer_tools()</b> or caller-supplied tool names. It adds nodes sequentially to an in-memory NetworkX DiGraph and writes a JSON-serialized payload to SQLite at the end.'),Image(str(OUT/'GraphGuard_Project_Architecture.png'),width=17.5*cm,height=8.1*cm),P('High-level architecture generated from actual source behavior. Retrieved content is only represented when supplied with the request. There is no retrieval client, LLM call, queue, identity provider, MCP server, or external tool connector.'),P('Component data flow: ExecuteRequest -> graph USER_INSTRUCTION -> optional RETRIEVED_CONTENT -> MODEL_DECISION -> TOOL_CALL -> PERMISSION_CHECK -> RISK_ASSESSMENT -> POLICY_DECISION -> optional TOOL_RESULT -> execution payload persisted in SQLite.'),PageBreak()]
    story += H('6. Core Technical Implementation')
    core_sections=[('6.1 Agent simulator and tool registry','<b>infer_tools()</b> performs deterministic keyword matching over transfer, delete, email, balance, customer and search. <b>TOOLS</b> maps six names to immutable Tool records with a permission, sensitivity value, category and lambda mock handler. Handlers return messages such as “Mock transfer recorded. No money moved.” This supports safe demonstration but is not an LLM agent or a real integration.'),('6.2 Dynamic interaction graph','<b>InteractionGraph.add()</b> creates UUID nodes containing id, UTC timestamp, event_type and metadata. It adds one directed “next” edge from the last node. <b>export()</b> returns lists of NetworkX node/edge tuples. The representation captures order but not a rich causal or branching graph.'),('6.3 Risk scoring','<b>RiskEngine.analyze()</b> combines tool sensitivity 0.32, permission gap 0.22, untrusted-source signal 0.16, sensitive sequence signal 0.15 and injection signal 0.15. The source signal is 70 only where nonempty retrieved content accompanies a tool with sensitivity at least 45. A sequence signal of 85 applies to transfer/email after customer record or balance access. The score is a transparent weighted sum and returns factors plus rationale.'),('6.4 Injection and policy','<b>INJECTION_RE</b> matches phrases including “ignore previous”, “system prompt”, “bypass”, “override instruction”, “exfiltrat” and “send password”. <b>PolicyEngine.evaluate()</b> blocks unknown tools, injection and missing permission before applying thresholds. Transfers/deletes require human approval. Scores >=70 block, score >=35 or sensitivity >=55 requires approval, otherwise allow. This ordering is critical: hard restrictions cannot be reduced by a score.'),('6.5 Approval and persistence','<b>init_db()</b> creates executions and approvals tables. Pending actions create a row with PENDING status. The approval endpoint updates status/reviewer; an approved state invokes the mock handler. A limitation is that approved execution does not update the original graph/execution payload with a post-approval result.'),('6.6 Evaluation and dashboard','<b>scenarios()</b> creates 4 benign, 12 dangerous and 4 legitimate-sensitive scenarios. <b>baseline()</b> models an always-allow agent, static permissions, and GraphGuard. <b>run_evaluation()</b> writes raw results, summary CSV, JSON metadata and a Matplotlib PNG. The Streamlit dashboard imports and calls the same Python service layer directly rather than making HTTP calls to the FastAPI server.')]
    for title,body in core_sections: story += [P(title,'H2G'),P(body)]
    story += [P('<b>Pseudocode - guarded execution</b>','H2G'),P('create graph; add instruction and optional retrieval; choose tools; for each tool: add decision/call/permission nodes; analyze risk; evaluate policy; execute mock tool only for ALLOW; persist pending approval otherwise; derive overall decision; save serialized execution.', 'CodeG'),PageBreak()]
    endpoints=[('GET','/health','Service availability','None','status and offline mode'),('GET','/tools','Registered mock tools','None','tool metadata'),('POST','/agent/execute','Run guarded simulation','ExecuteRequest','execution, graph, outcomes'),('POST','/risk/analyze','Analyze one tool request','ToolRequest','score, factors, rationale'),('POST','/policy/evaluate','Evaluate policy','ToolRequest','decision, reasons, risk'),('GET','/executions','List persisted executions','None','id, timestamp, decision'),('GET','/executions/{id}','Retrieve execution','path id','serialized payload or 404'),('GET','/graph/{id}','Alias of execution retrieval','path id','serialized graph/payload or 404'),('GET','/approvals','List approvals','None','approval rows'),('POST','/approvals/{id}/approve','Approve queued mock action','ApprovalAction','status/reviewer/mock result'),('POST','/approvals/{id}/reject','Reject queued action','ApprovalAction','status/reviewer'),('POST','/evaluation/run','Run suite','None','run metadata'),('GET','/evaluation/results','Latest run','None','latest JSON or 404'),('GET','/evaluation/results/{run_id}','Latest matching run only','path id','latest JSON or 404'),('GET','/evaluation/report','Alias of latest results','None','latest JSON or 404')]
    story += H('7. API Reference')+[tbl(['Method','Endpoint','Purpose','Request','Response'],endpoints,[1.25*cm,3.5*cm,4.25*cm,3.5*cm,4.4*cm]),P('Authentication is not implemented. Pydantic validates three body schemas. The explicit error behavior found is HTTP 404 for an unknown execution/approval or absent/mismatched latest evaluation. There is no dedicated exception middleware, authorization, rate limiting, or custom status design.'),PageBreak()]
    story += H('8. Current Development Status')+[tbl(['Module','Current status','Evidence','Remaining work'],status,[3.2*cm,3*cm,5.7*cm,5.1*cm]),P('Overall assessment: GraphGuard is genuinely functional as an offline educational prototype. It demonstrates graph event recording, explainable heuristic policy enforcement, SQLite persistence, a pending approval route, deterministic comparison evaluation and a local UI. It is not yet a production security platform, real LLM agent, real retrieval system, or MCP-enabled implementation.'),PageBreak()]
    metrics=latest['metrics']; rows=[[m['approach'],m['attack_success_rate'],m['task_success_rate'],m['false_positive_rate'],m['blocked_dangerous_actions'],m['policy_decision_accuracy'],m['average_execution_latency_ms'],m['human_approval_frequency'],m['f1']] for m in metrics]
    story += H('9. Experimental Results and Evaluation')+[P(f"The latest persisted evaluation run is <b>{latest['run_id']}</b>. It reports {latest['scenario_count']} scenarios per approach. Results below are simulated deterministic policy outcomes, not production benchmarks or external LLM measurements."),tbl(['Approach','Attack success %','Task success %','FP %','Blocked','Accuracy %','Latency ms','Approval %','F1'],rows,[2.5*cm,2*cm,1.8*cm,1.2*cm,1.25*cm,1.8*cm,1.7*cm,1.8*cm,1.1*cm]),Image(latest['artifacts']['chart'],width=16.5*cm,height=8.25*cm),P('Metric definitions in code: attack success means dangerous scenarios whose actual decision equals ALLOW; task success counts non-dangerous ALLOW or REQUIRE_HUMAN_APPROVAL; false positive means non-dangerous BLOCK. Precision, recall and F1 treat BLOCK as positive. Important caveat: all scenarios are authored in code and outputs derive from that same policy, so they demonstrate behavior rather than independent security efficacy.'),PageBreak()]
    story += H('10. Security Analysis')+[P('<b>Threat model.</b> Inputs include user instructions, untrusted retrieved text and requested tool names. The protected decision point is the simulated tool invocation. The trust boundary lies before mock handlers. GraphGuard protects against the explicitly matched injection phrases, unknown tools, missing permissions, selected sensitive sequences and high-impact actions requiring review.'),P('<b>Attack surface and gaps.</b> Keyword injection detection can miss paraphrases, encoded instructions, multilingual attacks, document provenance attacks and model-tool persuasion. “Retrieved content” is client supplied; no retrieval provenance exists. Permissions are plain strings sent by the caller, with no identity/authentication. SQLite audit rows can be modified by anyone with filesystem access. Approval reviewers are unauthenticated names. No secret management, sandbox, access token, network isolation, rate limiting, content signing or tamper-evident log exists.'),P('<b>Data protection.</b> The current records are mock strings only. This reduces demo risk but makes the system untested against actual sensitive data handling.'),PageBreak()]
    story += H('11. Installation and Execution Guide')+[P('<b>Prerequisites:</b> Python 3.11 or newer, pip, and optionally Docker. The repository currently uses the root app package.'),P('python -m venv .venv\n.\\.venv\\Scripts\\Activate.ps1\npip install -r requirements.txt\npython -m uvicorn app.main:app --reload\nstreamlit run app/dashboard.py\npython -m pytest -q\npython scripts/run_evaluation.py','CodeG'),P('Open http://127.0.0.1:8000/docs for Swagger when the server is running. Database initialization occurs through FastAPI startup or execute paths. Environment variables in .env.example are unused by current runtime. Docker support is scaffolded: docker compose up --build targets app.main:app. If “python” is unavailable, install Python and add it to PATH. If Streamlit is missing, rerun pip install -r requirements.txt. If a SQLite lock occurs, stop other local GraphGuard processes before retrying.'),PageBreak()]
    story += H('12. Roadmap and Team Contribution')+[P('<b>Immediate:</b> remove duplicate runtime copies or declare the canonical package; add API integration tests using a running test client; repair approval audit linkage; make database path/config explicit.'),P('<b>Short term:</b> authenticate users and reviewers, add policy configuration/versioning, tool input schemas, graph visualization and append-only audit records.'),P('<b>Advanced:</b> real provider abstraction, retrieved-document provenance, capability tokens, sandboxed execution, semantic injection classifier, independently curated adversarial corpus, repeated latency experiments and confidence intervals.'),P('<b>Research:</b> graph-based anomaly models, causal sequence analysis, benchmark comparison with tool-using LLMs, and an MCP adapter with strict least-privilege capabilities.'),P('<b>Team contribution evidence:</b> unavailable. Git has no commits, and source files do not record individual authorship. Suggested allocation for team verification only: Jivesh - agent/API integration; Gaurav - graph/risk/policy implementation; Himanshu - evaluation/dashboard/documentation. This is not a claim of historical contribution and must be confirmed by the team.')]
    appendices=[
      ('A. Schema Layer: app/models.py','The schema layer defines the three policy decisions as a string Enum and uses Pydantic fields for instruction length, permission lists, optional retrieval content, explicit requested tools and a reviewer name. It is the contract boundary for FastAPI bodies.','class ExecuteRequest(BaseModel):\n    instruction: str = Field(min_length=1, max_length=4000)\n    agent_permissions: list[str] = Field(default_factory=lambda: ["search", "read"])'),
      ('B. Tool Registry: app/core.py','The registry is a dictionary of Tool dataclasses. Each handler is a closure that returns mock JSON, establishing a safe teaching environment. There are no request-specific arguments to tool handlers.','TOOLS = {\n "search_documents": Tool(..., "search", 10, "read", ...),\n "transfer_funds": Tool(..., "transfer", 90, "financial", ...)\n}'),
      ('C. Interaction Graph: app/core.py','Graph nodes are created one at a time and joined from the previous node. This means every run has a deterministic event timeline. The metadata object is flexible, but no static node schema or graph database exists.','self.graph.add_node(node_id, id=node_id, timestamp=now(),\n                    event_type=event_type, metadata=metadata)\nif self.last: self.graph.add_edge(self.last, node_id, relationship="next")'),
      ('D. Risk Engine: app/core.py','The score is a weighted linear combination. Its explanation is factor-level, so it is suitable for a faculty demo. It should not be interpreted as a calibrated probability of compromise.','score = round(sum(raw[k] * self.weights[k] for k in self.weights), 2)\nrationale = [f"{k} contributed ..." for k, v in raw.items() if v]'),
      ('E. Policy Engine: app/core.py','Hard restrictions are tested before thresholds. This is the code-level guarantee that detected injection and missing permissions always block. The policy is embedded in Python rather than external configuration.','if not tool: return BLOCK\nif risk["injection_detected"]: return BLOCK\nif risk["permission_gap"]: return BLOCK\nif tool.name in {"transfer_funds", "delete_record"}: return APPROVAL'),
      ('F. SQLite Persistence: app/core.py','Two tables store serialized execution payloads and approvals. The payload includes the graph captured before eventual approval execution. SQLite is local-file persistence; the schema has no foreign key or migration tool.','CREATE TABLE IF NOT EXISTS executions (id TEXT PRIMARY KEY, created_at TEXT, decision TEXT, payload TEXT)\nCREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, execution_id TEXT, tool TEXT, status TEXT, created_at TEXT, reviewer TEXT)'),
      ('G. FastAPI Routing: app/main.py','The service has REST endpoints for health, tools, execution, risk, policy, graph, approvals and evaluation. Swagger is automatically exposed by FastAPI. No route has an authentication dependency.','@app.post("/agent/execute")\ndef agent_execute(req: ExecuteRequest): return execute(req)\n@app.post("/evaluation/run")\ndef evaluation_run(): return run_evaluation()'),
      ('H. Evaluation Scenarios: app/evaluation.py','The suite is assembled in Python, not read from data files. It covers four benign, twelve dangerous and four legitimate-sensitive rows. The GraphGuard baseline runs actual execute() for each row.','benign = [...]\nattacks = [...]\napprovals = [...]\nfor approach in ["Unprotected Agent", "Static Permission Controls", "GraphGuard"]: ...'),
      ('I. Metrics: app/evaluation.py','Metrics are calculated from the result DataFrame. The code protects division by zero. Latency is process-local measurement around each baseline function; unprotected/static latency rounds to zero in the saved report.','precision = tp/(tp+fp) if tp+fp else 0\nrecall = tp/(tp+fn) if tp+fn else 0\nattack_success_rate = 100 * allowed_dangerous / dangerous'),
      ('J. Dashboard: app/dashboard.py','Seven Streamlit tabs provide overview, playground, interaction graph rows, risk factors, approval list, evaluation table/chart and audit list. The dashboard directly imports core functions instead of invoking FastAPI over HTTP.','tabs = st.tabs(["Overview", "Agent Playground", "Interaction Graph",\n                "Risk Analysis", "Approval Center", "Security Evaluation", "Audit Logs"])'),
      ('K. Tests: tests/','The two test files contain six tests. They call core functions or route callables directly. They do not start an ASGI server, validate Swagger, test malformed JSON, run Docker, or verify Streamlit.','test_injection_blocks_even_with_permission\ntest_unknown_tool_is_blocked\ntest_transfer_requires_approval\ntest_health_and_tools\ntest_execute_graph_and_approval_flow\ntest_evaluation_endpoint'),
      ('L. Runtime Layout and Evidence','The canonical runtime is root app/ because the Dockerfile command is app.main:app and tests import app. backend/app is a duplicate copy and frontend/app.py is a duplicate dashboard. Reports provide run evidence but are overwritten at reports/latest_evaluation.json.','CMD ["uvicorn", "app.main:app", "--host", "0.0.0.0", "--port", "8000"]\nlatest evaluation: aa2d9424-ead9-4143-941c-8a1648a32563')]
    for title,desc,code in appendices:
        story += [PageBreak(),P(title,'H1G'),P(desc),P('Source-derived excerpt','H2G'),P(code,'CodeG'),P('Interpretation','H2G'),P('This appendix is an implementation-level reference for the current codebase. It documents what is present today and does not imply capabilities beyond the cited behavior.')]
    return story

def status_report():
    story=cover('Development Status Report','Concise current-state assessment for faculty review')
    story+=H('Verified Current State')+[P('Active root implementation: 5 primary Python modules. Test files: 2. Test functions: 6. Latest observed test result: 6 passed, 0 failed; FastAPI emits two deprecation warnings for @app.on_event. Current evaluation artifact: 20 deterministic scenarios per baseline. No Git commit history is present.'),tbl(['Indicator','Verified finding'],[('Runtime','Root app.main:app, offline mocked tools'),('Working policy outcomes','ALLOW, BLOCK, REQUIRE_HUMAN_APPROVAL'),('Persistent data','SQLite executions and approvals tables'),('Tests','6 passed / 0 failed'),('Real LLM or MCP','Not implemented'),('Dashboard','Streamlit local UI, direct Python calls'),('Deployment','Docker files present; not verified in this review')],[5*cm,12.2*cm]),PageBreak()]
    story+=H('Module-by-Module Progress')+[tbl(['Module','Status','Key evidence','Next priority'],status,[3.2*cm,3*cm,5.7*cm,5.1*cm]),PageBreak()]
    story+=H('Management Conclusion')+[P('The project is ready to demonstrate as an offline academic prototype. The most defensible presentation claim is that GraphGuard implements a deterministic, explainable policy layer around simulated tools and evaluates it against two simplified baselines. It should not be presented as a deployed LLM security control, an MCP system, or validated production benchmark.'),P('Critical next steps before external tool connection: authentication, validated tool arguments, trusted retrieval provenance, robust injection defenses, sandboxing, immutable audit logs, and independent security evaluation.')]
    return story

def tech_report():
    story=cover('Technology Stack Reference','Verified technologies, libraries and implementation status')
    story+=H('Verified Stack')+[tbl(['Technology','Where used','Purpose','Why chosen / status'],tech,[3*cm,3.7*cm,4.1*cm,6.2*cm]),PageBreak()]
    story+=H('Important Non-Implementations')+[P('The requirements file contains NumPy and scikit-learn, but no active root Python module imports either library. .env.example lists OpenAI-compatible configuration, but no active implementation reads these variables or makes an LLM request. No MCP dependency, client, server, tool protocol or integration appears in the codebase. These are planned configuration ideas, not deployed technologies.'),P('The only active “agent” is deterministic keyword inference in app/core.py. The only tool execution is mock lambda output. This design is appropriate for an offline demonstration but needs clear wording in evaluations and presentations.')]
    return story

def csvs():
    with (OUT/'GraphGuard_Module_Inventory.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f); w.writerow(['Location','Responsibility','Important symbols','Role']); w.writerows(inventory)
    with (OUT/'GraphGuard_Development_Status.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f); w.writerow(['Module','Current status','Evidence in codebase','Remaining work']); w.writerows(status)

